def distinct_count(grid):
    """Count distinct non-zero values in a grid."""
    seen = set()
    for row in grid:
        for x in row:
            if x != 0:
                seen.add(x)
    return len(seen)

def find_3x3_regions(grid):
    """Find all 3x3 regions in the grid."""
    h, w = len(grid), len(grid[0])
    regions = []
    for i in range(h - 2):
        for j in range(w - 2):
            region = [grid[i+di][j+dj] for di in range(3) for dj in range(3)]
            distinct = distinct_count(region)
            regions.append((i, j, region, distinct))
    return sorted(regions, key=lambda x: (-x[3], -x[0], -x[1]))

